import type { SchoolForm, SchoolFormPage } from '@/lib/school-forms'

/**
 * Per-school application questions, read field by field off each school's own
 * live application form.
 *
 * Generated, not hand-written, and deliberately so: these are 5,627 questions
 * across 133 schools in the schools' own wording, and wording is the whole
 * point. A student who drafts against a paraphrase has not prepared the answer
 * they will paste. Regenerate rather than edit - schools revise these annually.
 *
 * The shape of what is here is worth knowing before reading it. The Common App
 * member section is short: most schools ask between eight and twenty questions,
 * and the spine repeats - start term, testing opt-in, financial aid, intended
 * major, previously applied, and the family block. The University of
 * California is the outlier at 352 questions, because the UC application is not
 * a supplement to anything: it restates the entire academic record course by
 * course, and one submission covers every campus. That is why eight campuses
 * share a single form object below.
 *
 * Schools absent from the source catalogue are modelled instead, in
 * lib/school-forms-extended.ts, and marked `verified: false` so the UI can say
 * which kind a student is looking at.
 */

