  'Indiana University Bloomington': {
    cycle: CYCLE,
    verified: true,
    sourceNote: 'Indiana University Bloomington\'s own application questions, read from the live form.',
    pages: [
      { key: 'general', label: 'General', kind: 'fields', fields: [
        { key: 'termPlanPreferredStartTerm0', label: 'Term & Plan Preferred start term:', type: 'select', required: true },
        { key: 'areYouInterestedInBeing1', label: 'Are you interested in being considered for admission to the Hutton Honors College? Consideration for admission to the Hutton Honors College requires a separate application. If you select yes to the question above, a link to the Hutton Honors College Application will be available in your IU Admissions portal checklist once you submit this IU Application. For Hutton admission and scholarship consideration, your IU Application must be completed by November 1, and your Hutton Honors Application must be submitted by February 1. For Hutton admission without scholarship consideration, your IU Application must be completed by February 1, and your Hutton Honors Application must be submitted by March 1. For more information, including important deadline information for Hutton Honors College Scholarship consideration, please visit our website .', type: 'select', required: true },
        { key: 'requiredByIndianaUniversityBloomington2', label: 'Required by Indiana University Bloomington - Flagship Campus Behavioral Disclosure Indiana University is committed to maintaining a safe learning environment. As part of that commitment, we require applicants to disclose if they: -have been subject to formal disciplinary action (including for example, but not limited to, suspension or expulsion) for a violent offense or sexual misconduct at any high school, post-secondary institution, college or university; -have been charged with or convicted of a crime (or a foreign legal equivalent) that has not been expunged by a court; and/or -have engaged in behavior that caused injury to person(s) or personal property (including for example, but not limited to, vandalism or behavior that led to a restraining order against you) which resulted in some sort of formal discipline or intervention. A previous disciplinary action, charge, conviction or conduct of the sort identified here does not automatically disqualify applicants from admission to Indiana University, but they do require review by the campus admissions committee. PLEASE NOTE : By submitting your application to Indiana University, you acknowledge and agree that you have a continuing obligation to inform the University of: -any formal disciplinary action at an educational institution; -any legal charges and/or convictions (or foreign legal equivalents) that have not been expunged by a court; and/or -any behavior that causes injury to person(s) or property that results in some form of discipline or intervention. You must provide updated information to the campus admissions committee prior to class attendance. At that time, the campus admissions committee will review the information provided and may consider whether to delay or rescind your admission to the University. Behavioral/Discipline Disclosure Have you been subject to disciplinary action (including for example, but not limited to, suspension or expulsion) for a violent offense or sexual misconduct (including for example, but not limited to, physical violence; hazing; sexual harassment, violence, assault or exploitation; or similar offense) at any high school, post-secondary institution, college or university?', type: 'select', required: true },
        { key: 'haveYouEverBeenArrested3', label: 'Have you ever been arrested or convicted of a crime (or a foreign legal equivalent) that has not been expunged by a court? Also select “Yes” if you have any currently pending criminal charges (or a foreign legal equivalent) against you.', type: 'select', required: true },
      ] },
      { key: 'academics', label: 'Academics', kind: 'fields', fields: [
        { key: 'firstChoiceMajorInterestPlease0', label: 'First Choice Major Interest Please indicate your intended major below. This is the academic plan that will be used for your consideration for admission. We strongly encourage you to visit our online major tool before choosing your first choice major. Majors in the Kelley School of Business, IU School of Nursing, and Jacobs School of Music have limited capacity. If you are interested in a major in one of these schools, it must be listed as your first choice major. The second-choice dropdown does not include limited capacity majors. Other majors have the capacity to accommodate all interested students admitted to Indiana University.', type: 'select', required: true },
        { key: 'secondChoiceMajorInterestYour1', label: 'Second Choice Major Interest Your first choice intended major will be given full consideration; however, you may be admitted to your second-choice major. In selecting a second-choice major, you should have a genuine interest in pursuing that field if admitted. FAQ about choosing a major at IU .', type: 'select', required: true },
        { key: 'ifYourPlansIncludeProfessional2', label: 'If your plans include professional or graduate school, please select all interests that apply. Maximum value 7.', type: 'text' },
        { key: 'testScoresApplicantsToIndiana3', label: 'Test Scores Applicants to Indiana University Bloomington - Flagship Campus have the opportunity to self-report their test scores on the application for admission or to apply without providing test scores. The campus does prefer that students share any available standardized test scores as part of their application as one element of academic evidence, noting that such evidence may strengthen a student’s application. Visit our website for more information about the use of test scores in admissions. I want my ACT/SAT/CLT scores included in the review of my application for IU Bloomington - Flagship Campus.', type: 'radio', required: true, optionsLiteral: true, options: ['Yes, include my scores', 'No, do not include my scores'] },
      ] },
      { key: 'contacts', label: 'Contacts', kind: 'fields', fields: [
        { key: 'ifYouWishToBe0', label: 'If you wish to be contacted via mobile phone, please provide your phone number. Contact methods may include phone calls generated from an automated telephone dialing system or text messaging.', type: 'select' },
        { key: 'doWeHavePermissionTo1', label: 'Do we have permission to contact your parent or legal guardian about your application?', type: 'select', required: true },
        { key: 'ifYouHaveHadCorrespondence2', label: 'If you have had correspondence or interviews with an IU official (admissions counselor, alumni representative, faculty member, coach, etc.), please list their name, department and dates if known: Maximum 128 characters.', type: 'text' },
      ] },
      { key: 'writing', label: 'Writing', kind: 'writing' },
      { key: 'additional', label: 'Additional', kind: 'notes' },
    ],
  },
